if (typeof window !== 'undefined') {
  window.INITIAL_LEADS = INITIAL_LEADS;
  window.DEFAULT_LEADS = INITIAL_LEADS;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { INITIAL_LEADS, DEFAULT_LEADS: INITIAL_LEADS };
}
